void nsb_deactivate_external_directors() noexcept {
    std::vector<std::shared_ptr<DirectorRuntime>> runtimes;
    {
        std::lock_guard<std::mutex> lock(external_registry_mutex);
        std::vector<std::weak_ptr<DirectorRuntime>> live;
        live.reserve(external_registry.size());
        for (const std::weak_ptr<DirectorRuntime>& weak : external_registry) {
            if (std::shared_ptr<DirectorRuntime> runtime = weak.lock()) {
                runtimes.push_back(runtime);
                live.push_back(runtime);
            }
        }
        external_registry.swap(live);
    }
    for (const std::shared_ptr<DirectorRuntime>& runtime : runtimes) {
        runtime->Deactivate();
    }
}

